import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this), address(this)); }

    // fuzz the _baseToken and another arg to ensure broad coverage
    function testFuzz_property(address _baseToken, uint128 _vBase) public {
        // keep nft as this contract address to be valid and wide
        address _nft = address(this);
        uint128 _virtualNftReserves = 1;
        uint56 _changeFee = 0;
        uint16 _feeRate = 0;
        bytes32 _merkleRoot = bytes32(0);
        bool _useStolenNftOracle = false;
        bool _payRoyalties = false;

        // Avoid the trivial invalid case where initialization reverts due to FeeRateTooHigh
        // or already-initialized won't occur because fresh instance. feeRate bound is wide already.
        // Call initialize with fuzzed base token and other params.
        bool ok;
        try c.initialize(_baseToken, _nft, _vBase, _virtualNftReserves, _changeFee, _feeRate, _merkleRoot, _useStolenNftOracle, _payRoyalties) {
            ok = true;
